/* ---------- normalisation et contrôle des réponses ---------- */
function strict(s){return String(s).toLowerCase().replace(/[’`´]/g,"'").replace(/[¿¡?!.,;:«»"“”()·…\-？！，。、；：「」『』（）]/g,' ').replace(/\s+/g,' ').trim();}
function loose(s){return strict(s).normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/ß/g,'ss').replace(/ς/g,'σ').replace(/'/g,'');}
function matchText(val,accepts){
 const s=strict(val),l=loose(val);
 if(!s)return{ok:false};
 for(const a of accepts){if(strict(a)===s)return{ok:true};}
 for(const a of accepts){if(loose(a)===l)return{ok:true,near:true};}
 const ns=x=>loose(x).replace(/\s/g,'');for(const a of accepts){if(ns(a)&&ns(a)===ns(val))return{ok:true,near:true};}
 return{ok:false};
}
function parseNum(v){const t=String(v).replace(/^\s*x\s*=/i,'').replace(/\s|€|%| /g,'').replace(',','.').replace('−','-');if(!/^[-+]?\d*\.?\d+$/.test(t))return NaN;return parseFloat(t);}
function parseFrac(v){const t=String(v).replace(/\s/g,'');let m=t.match(/^(-?\d+)\/(-?\d+)$/);if(m&&+m[2]!==0)return{n:+m[1],d:+m[2]};const x=parseNum(t);if(!isNaN(x)&&Number.isInteger(x))return{n:x,d:1};return null;}

