/* ---------- contenus : échecs ---------- */
function pieceSvg(k,white){const p=PIECE_PATHS[k],s=78/1496,w=(p.b[2]-p.b[0])*s,tx=(100-w)/2-p.b[0]*s;
 return `<svg class="pc ${white?'w':'b'}" viewBox="0 0 100 100" aria-hidden="true" focusable="false"><path transform="translate(${tx.toFixed(2)} 89) scale(${s.toFixed(5)} -${s.toFixed(5)})" d="${p.d}"/></svg>`;}
const GLYPH={k:1,q:1,r:1,b:1,n:1,p:1};
const PNAME={k:'roi',q:'dame',r:'tour',b:'fou',n:'cavalier',p:'pion'};
const FILES='abcdefgh';
function parseFen(f){const b={};f.split(' ')[0].split('/').forEach((r,ri)=>{let fi=0;for(const ch of r){if(/\d/.test(ch))fi+=+ch;else{b[FILES[fi]+(8-ri)]=ch;fi++;}}});return b;}
function boardHtml(fen,o={}){
 const b=fen?parseFen(fen):{};let h=`<div class="board" role="grid" aria-label="${esc(o.label||'Échiquier')}">`;
 for(let r=8;r>=1;r--){h+='<div class="brow" role="row">';for(let fi=0;fi<8;fi++){
  const sq=FILES[fi]+r,ch=b[sq],dark=(fi+r)%2===1,w=ch&&ch===ch.toUpperCase();
  let lbl=sq;if(ch)lbl+=', '+PNAME[ch.toLowerCase()]+(w?' blanc':' noir');
  const cls=`sq ${dark?'d':'l'}${o.hl===sq?' hl':''}`;
  const inner=(ch?pieceSvg(ch.toLowerCase(),w):'')+
   (o.coords&&r===1?`<span class="cf" aria-hidden="true">${FILES[fi]}</span>`:'')+(o.coords&&fi===0?`<span class="cr" aria-hidden="true">${r}</span>`:'');
  h+=o.inter?`<button class="${cls}" role="gridcell" data-act="sq" data-sq="${sq}" aria-label="${lbl}">${inner}</button>`:`<div class="${cls}" role="gridcell" aria-label="${o.hl===sq?'case à trouver':lbl}">${inner}</div>`;
 }h+='</div>';}
 return h+'</div>';
}
