const NOTE_FR=['Do','Ré','Mi','Fa','Sol','La','Si'],NOTE_EN=['C','D','E','F','G','A','B'];
function stepFreq(s){const oct=Math.floor(s/7),n=s%7,midi=12*(oct+1)+[0,2,4,5,7,9,11][n];return 440*Math.pow(2,(midi-69)/12);}
const midiFreq=m=>440*Math.pow(2,(m-69)/12);
function staffSvg(step,clef){
 const bottom=clef==='g'?30:18,Y=s=>100-(s-bottom)*6;let h=`<svg class="staff" viewBox="0 0 260 160" role="img" aria-label="Portée en clé de ${clef==='g'?'sol':'fa'} avec une note">`;
 for(let k=0;k<5;k++){const y=100-k*12;h+=`<line class="sl" x1="8" x2="252" y1="${y}" y2="${y}"/>`;}
 h+=clef==='g'?`<path class="clef" transform="translate(8 98.5) scale(0.0705 -0.0705)" d="${CLEF_G}"/>`:`<path class="clef" transform="translate(10 99.2) scale(0.065 -0.065)" d="${CLEF_F}"/>`;
 if(step<bottom)for(let s=bottom-2;s>=step;s-=2)h+=`<line class="ll" x1="146" x2="184" y1="${Y(s)}" y2="${Y(s)}"/>`;
 if(step>bottom+8)for(let s=bottom+10;s<=step;s+=2)h+=`<line class="ll" x1="146" x2="184" y1="${Y(s)}" y2="${Y(s)}"/>`;
 const cy=Y(step);h+=`<ellipse class="head" cx="165" cy="${cy}" rx="9" ry="6.5" transform="rotate(-20 165 ${cy})"/>`;
 h+=step<bottom+4?`<line class="stem" x1="173.5" y1="${cy-2}" x2="173.5" y2="${cy-44}"/>`:`<line class="stem" x1="156.5" y1="${cy+2}" x2="156.5" y2="${cy+44}"/>`;
 return h+'</svg>';
}
function figSvg(kind){
 const open=kind==='ronde'||kind==='blanche';let h=`<svg class="fig" viewBox="0 0 80 110" role="img" aria-label="Figure de note à identifier">`;
 h+=`<ellipse class="${open?'ho':'hf'}" cx="34" cy="84" rx="${kind==='ronde'?14:12}" ry="9" transform="rotate(-20 34 84)"/>`;
 if(kind!=='ronde')h+=`<line class="stem" x1="45" y1="81" x2="45" y2="16"/>`;
 if(kind==='croche'||kind==='double')h+=`<path class="hf" d="M45 16c4 12 20 16 15 37 1-14-7-19-15-22z"/>`;
 if(kind==='double')h+=`<path class="hf" d="M45 31c4 12 20 16 15 37 1-14-7-19-15-22z"/>`;
 return h+'</svg>';
}
