function face(cx,cy,mood,s=1){
 const e=6*s,ey=cy-4*s,dx=11*s;
 let eyes=`<g class="eyes"><ellipse cx="${cx-dx}" cy="${ey}" rx="${e}" ry="${e*1.15}" fill="#fff"/><ellipse cx="${cx+dx}" cy="${ey}" rx="${e}" ry="${e*1.15}" fill="#fff"/>`+
  `<circle cx="${cx-dx+1.5*s}" cy="${ey+1*s}" r="${3.4*s}" fill="#2A2550"/><circle cx="${cx+dx+1.5*s}" cy="${ey+1*s}" r="${3.4*s}" fill="#2A2550"/>`+
  `<circle cx="${cx-dx+2.6*s}" cy="${ey-0.4*s}" r="${1.2*s}" fill="#fff"/><circle cx="${cx+dx+2.6*s}" cy="${ey-0.4*s}" r="${1.2*s}" fill="#fff"/></g>`;
 if(mood==='sad')eyes+=`<path d="M${cx-dx-6*s} ${ey-9*s} l${10*s} ${3*s}M${cx+dx+6*s} ${ey-9*s} l${-10*s} ${3*s}" stroke="#2A2550" stroke-width="${2.2*s}" stroke-linecap="round"/>`;
 const my=cy+10*s;
 const mouth=mood==='sad'?`<path d="M${cx-7*s} ${my+3*s} q${7*s} ${-7*s} ${14*s} 0" stroke="#2A2550" stroke-width="${2.6*s}" fill="none" stroke-linecap="round"/>`:
  mood==='wow'?`<ellipse cx="${cx}" cy="${my}" rx="${4.5*s}" ry="${5.5*s}" fill="#2A2550"/><ellipse cx="${cx}" cy="${my+2.5*s}" rx="${2.6*s}" ry="${2*s}" fill="#FF7A8A"/>`:
  `<path d="M${cx-9*s} ${my-2*s} q${9*s} ${11*s} ${18*s} 0z" fill="#2A2550"/><path d="M${cx-4.5*s} ${my+3.2*s} q${4.5*s} ${3*s} ${9*s} 0" fill="#FF7A8A"/>`;
 return eyes+`<ellipse cx="${cx-dx-4*s}" cy="${my-1*s}" rx="${4*s}" ry="${2.6*s}" fill="#FF9F7A" opacity=".55"/><ellipse cx="${cx+dx+4*s}" cy="${my-1*s}" rx="${4*s}" ry="${2.6*s}" fill="#FF9F7A" opacity=".55"/>`+mouth;
}
/* Bras : levés pour « cheer » (victoire, combo), sur les côtés sinon. */
const ARM_AT={bia:[24,74,96,74],kubi:[20,72,100,72],pion:[42,78,78,78],melo:[34,86,90,80]};
function arms(kind,mood){const a=ARM_AT[kind]||ARM_AT.bia,up=mood==='cheer',st='stroke="#2A2550" stroke-width="5" stroke-linecap="round" fill="none"';
 const l=up?`M${a[0]} ${a[1]} q-10 -14 -6 -30`:mood==='sad'?`M${a[0]} ${a[1]} q-8 10 -4 20`:`M${a[0]} ${a[1]} q-12 4 -14 16`,
  r=up?`M${a[2]} ${a[3]} q10 -14 6 -30`:mood==='sad'?`M${a[2]} ${a[3]} q8 10 4 20`:`M${a[2]} ${a[3]} q12 4 14 16`;
 const hand=(d,x,y)=>`<circle cx="${x}" cy="${y}" r="5" fill="#FFF3C4" stroke="#2A2550" stroke-width="2.5"/>`;
 const end=(x,y,up2,dir)=>up2?[x+dir*-6,y-30]:mood==='sad'?[x+dir*-4,y+20]:[x+dir*-14,y+16];
 const [lx,ly]=end(a[0],a[1],up,1),[rx,ry]=end(a[2],a[3],up,-1);
 return `<g class="arms"><path class="arm l" d="${l}" ${st}/><path class="arm r" d="${r}" ${st}/>${hand(0,lx,ly)}${hand(0,rx,ry)}</g>`;}
