function reviewSet(p){
 let keys=shuffle(dueKeys(p));if(keys.length<8){const more=Object.keys(p.srs).filter(k=>!keys.includes(k)&&byId(k.split('|')[0])).sort((a,b)=>p.srs[a].b-p.srs[b].b);keys=keys.concat(more.slice(0,8-keys.length));}
 const ex=keys.slice(0,10).map(k=>{const [cid,ui,ii]=k.split('|'),c=byId(cid);if(!c||!c.units[+ui]||!c.units[+ui].items[+ii])return null;const o=itemObj(c,+ui,+ii),b=p.srs[k].b;
  const uk=c.units[+ui].kind;if(uk==="gram"&&b<3)return exGram(c,o);if(uk==="vocab"&&b<2)return exPic(c,o);
  return b>=3?exType(c,o):b===2?exBuild(c,o):(Math.random()<.5?exF2T(c,o):exListen(c,o));}).filter(Boolean);
 COURSES.filter(c=>c.kind==='gen').forEach(c=>{const opened=c.units.map((u,i)=>i).filter(i=>done(p,c,i)>0);if(opened.length){for(let k=0;k<2;k++){const ui=pick(opened);ex.push(unitEx(c.units[ui],Math.min(2,done(p,c,ui)-1),rnd(50)));}}});
 return shuffle(ex);
}

