function toast(msg){let t=$('.toast');if(!t){t=document.createElement('div');t.className='toast';t.setAttribute('role','status');document.body.appendChild(t);}t.textContent=msg;t.hidden=false;clearTimeout(toastT);toastT=setTimeout(()=>{t.hidden=true;},2600);}
function applySize(){document.documentElement.classList.remove('size-l','size-xl');if(S.set.size==='l')document.documentElement.classList.add('size-l');if(S.set.size==='xl')document.documentElement.classList.add('size-xl');}
function avatar(p){return `<span class="avatar ${p.color}" aria-hidden="true">${esc(p.name.trim().charAt(0).toUpperCase()||'?')}</span>`;}
function topbar(){const p=me();fresh(p);const cur=v=>view===v?'aria-current="page"':'';
 return `<header class="topbar"><div class="topin">
  <button class="logo" data-act="home" aria-label="Bialingo, accueil">${LOGO}<span><b>Bia</b>lingo</span></button>
  <nav class="nav" aria-label="Navigation principale"><button data-act="home" ${cur('home')}${view==='course'?'aria-current="page"':''}>Cours</button><button data-act="family" ${cur('family')}>Famille</button><button data-act="settings" ${cur('settings')}>Réglages</button></nav>
  <div class="stats"><span class="pill" title="Série de jours consécutifs">${ICON.flame}<span>${p.streak}</span><span class="sr">jours de série</span></span>
  <span class="pill xp" title="Points d'expérience">${ICON.bolt}<span>${p.xp}</span><span class="sr">points d'expérience</span></span>
  <button class="avatar ${p.color}" data-act="family" aria-label="Profil actif : ${esc(p.name)}. Changer de profil">${esc(p.name.trim().charAt(0).toUpperCase())}</button></div>
 </div></header>`;}
function ring(p){const g=S.set.goal,v=Math.min(1,p.daily.xp/g),C=2*Math.PI*36;
 return `<div class="ring" role="img" aria-label="Objectif du jour : ${p.daily.xp} sur ${g} XP"><svg viewBox="0 0 84 84"><circle class="track" cx="42" cy="42" r="36"/><circle class="val" cx="42" cy="42" r="36" stroke-dasharray="${C.toFixed(1)}" stroke-dashoffset="${(C*(1-v)).toFixed(1)}"/></svg><span class="num">${p.daily.xp}<br><small>/ ${g} XP</small></span></div>`;}
function tile(p,c){const pct=coursePct(p,c),lv=currentLevel(p,c);return `<button class="tile ${c.color}" data-act="course" data-id="${c.id}"><span class="code">${c.code}</span><span class="name">${esc(c.name)}</span><span class="lvchip">Niveau : ${lvName(c,lv)}</span><span class="sub">${c.units.length} unités · ${pct} %</span><span class="prog" aria-hidden="true"><span data-w="${pct}"></span></span>${mascot(courseMascot(c),'happy')}</button>`;}
