function nextLesson(p,c){const o=order(c);for(const ui of o){if(!unitDone(p,c,ui))return[ui,done(p,c,ui)];}return[o[o.length-1],2];}
function renderCourse(){
 precacheCourse(curCourse);const p=me(),c=curCourse,pct=coursePct(p,c),[nu,nl]=nextLesson(p,c),LN=['Découverte','Pratique','Maîtrise'];let z=0;
 const node=(ui,li)=>{const open=unitOpen(p,c,ui),dn=done(p,c,ui),fin=dn>=3,isDone=dn>li,can=open&&li<=dn,cur=ui===nu&&li===nl&&!fin;
  const st=isDone?'done':cur?'current':can?'open':'locked',ic=isDone?NODE_ICON.check:can?NODE_ICON.star:NODE_ICON.lock,pos=z++%4;
  return `<div class="nwrap z${pos}">${cur?'<span class="startbub">Commencer</span>':''}<button class="node ${st}" data-act="lesson" data-u="${ui}" data-l="${li}" ${can?'':'disabled'} aria-label="Unité ${order(c).indexOf(ui)+1}, leçon ${li+1} : ${LN[li]}${isDone?', terminée':can?'':', verrouillée'}">${ic}</button><span class="nlabel">${LN[li]}</span></div>`;};
 const turbo=ui=>{const fin=done(p,c,ui)>=3,pos=z++%4;return `<div class="nwrap z${pos}"><button class="node turbo ${fin?'done':''}" data-act="turbo" data-u="${ui}" aria-label="Test Turbo de l'unité ${order(c).indexOf(ui)+1}${fin?', unité validée':''}">${NODE_ICON.trophy}</button><span class="nlabel">Turbo</span></div>`;};
 const unit=ui=>{const u=c.units[ui],open=unitOpen(p,c,ui),dn=done(p,c,ui);
  return `<li class="unit ${open?'':'locked'}"><div class="ubanner"><div><span class="eyebrow">Unité ${order(c).indexOf(ui)+1}</span><h3>${esc(u.t)}</h3><span class="badge ${dn>=3?'done':''}">${dn>=3?'Terminée':`${dn}/3 leçons`}</span></div>${u.tip?`<details class="tip" ${ui===nu&&dn<3?'open':''}><summary>Astuce</summary><p>${esc(u.tip)}</p></details>`:''}</div>
  <div class="nodes">${[0,1,2].map(li=>node(ui,li)).join('')}${turbo(ui)}</div></li>`;};
 app.innerHTML=topbar()+`<main class="wrap" id="main">
 <section class="chead ${c.color}"><div class="top"><button class="btn small" data-act="home">${ICON.back} Cours</button><span class="code badge">${c.code}</span></div>
  <div class="chead-row">${mascot(courseMascot(c),'happy','float')}<div><h1>${esc(c.name)}</h1><p class="muted">${pct} % terminé · niveau actuel : ${lvName(c,currentLevel(p,c))}</p></div></div><span class="prog" aria-hidden="true"><span data-w="${pct}"></span></span></section>
 ${levelsOf(c).map(lv=>`<section class="lvl lv${lv}" aria-labelledby="lv-${lv}"><div class="lvhead"><div><span class="eyebrow">Niveau ${levelsOf(c).indexOf(lv)+1} sur ${levelsOf(c).length}</span><h2 id="lv-${lv}">${lvName(c,lv)}</h2><p>${lvTip(c,lv)}</p></div>
  ${levelDone(p,c,lv)?'<span class="badge done">Niveau validé</span>':`<button class="btn small cta" data-act="leveltest" data-lv="${lv}">${NODE_ICON.bolt} Tester ce niveau</button>`}</div>
  <ol class="units">${order(c).filter(ui=>(c.units[ui].lv||0)===lv).map(unit).join('')}</ol></section>`).join('')}
 </main>`;
 const cur=$('.node.current');if(cur&&!reduceMotion())setTimeout(()=>{try{cur.scrollIntoView({block:'center'});}catch(x){}},80);
}
